<?php $item_value=function($item,$key,$default=''){return is_array($item)?($item[$key]??$default):($item->{$key}??$default);}; $response_for=function($item_id,$area_id=0)use($responses){return $responses[$item_id.':'.$area_id]??null;}; ?>
<div id="page-content" class="page-wrapper clearfix"><div class="card"><div class="page-title clearfix"><div><h1><i data-feather="clipboard" class="icon"></i> <?php echo esc($laudo->number); ?> - <?php echo esc($laudo->title); ?></h1><p class="text-muted mb0"><?php echo esc($laudo->client_name); ?> · <?php echo esc($laudo->type_name ?: $laudo->type_code); ?></p></div><div class="title-button-group"><a class="btn btn-default" href="<?php echo get_uri('engenharia/laudos/view/' . $laudo->id); ?>"><?php echo app_lang('back'); ?></a></div></div><div class="card-body pt0"><div class="row g-3 mb15"><div class="col-md-4"><label><?php echo app_lang('engenharia_current_area'); ?></label><select id="inspection-area" class="form-select"><option value="0"><?php echo app_lang('engenharia_all_areas'); ?></option><?php foreach($areas as $area){ ?><option value="<?php echo $area->id; ?>"><?php echo esc($area->name); ?></option><?php } ?></select></div><div class="col-md-4"><label><?php echo app_lang('engenharia_progress'); ?></label><div class="progress mt10" style="height:22px"><div id="inspection-progress-bar" class="progress-bar" style="width:<?php echo $summary['total']?round($summary['answered']/$summary['total']*100):0; ?>%"></div></div><small id="inspection-progress-label"><?php echo (int)$summary['answered']; ?> / <?php echo (int)$summary['total']; ?></small></div><div class="col-md-4 d-flex align-items-end"><div class="btn-group w-100"><button class="btn btn-default inspection-filter active" data-filter="all"><?php echo app_lang('all'); ?></button><button class="btn btn-default inspection-filter" data-filter="pending"><?php echo app_lang('engenharia_pending'); ?></button><button class="btn btn-default inspection-filter" data-filter="nonconforming"><?php echo app_lang('engenharia_nonconforming'); ?></button></div></div></div><div class="alert alert-info"><strong><?php echo app_lang('engenharia_pending'); ?>:</strong> <span id="pending-count"><?php echo (int)$summary['pending']; ?></span> · <?php echo app_lang('engenharia_inspection_instruction'); ?></div><?php if($groups){foreach($groups as $group){$gid=(int)$item_value($group,'id'); ?><div class="card inspection-group mb15" data-group="<?php echo $gid; ?>"><div class="card-header clearfix"><h5 class="mb0 float-start"><?php echo esc($item_value($group,'title')); ?></h5><span class="badge bg-light text-dark float-end group-count" data-group-count="<?php echo $gid; ?>"></span></div><div class="card-body"><?php foreach($items as $item){if((int)$item_value($item,'group_id')!==$gid)continue;$iid=(int)$item_value($item,'id');$resp=$response_for($iid,0);$value=$resp->response_value??'';$conforming=$resp->is_conforming??null;$pending=!$resp; ?><div class="inspection-item border-bottom pb15 mb15 <?php echo $pending?'is-pending':''; ?> <?php echo $conforming===0?'is-nonconforming':''; ?>" data-item-id="<?php echo $iid; ?>" data-pending="<?php echo $pending?1:0; ?>" data-nonconforming="<?php echo $conforming===0?1:0; ?>"><div class="row g-3"><div class="col-lg-7"><strong><?php echo esc($item_value($item,'code')); ?> — <?php echo esc($item_value($item,'title') ?: $item_value($item,'question')); ?></strong><p class="mb5"><?php echo nl2br(esc($item_value($item,'question'))); ?></p><?php if($item_value($item,'inspector_instruction')){ ?><small class="text-muted d-block"><i data-feather="info" class="icon-14"></i> <?php echo nl2br(esc($item_value($item,'inspector_instruction'))); ?></small><?php } ?><?php if($item_value($item,'norm_reference')){ ?><small class="text-muted d-block"><?php echo app_lang('engenharia_norm_reference'); ?>: <?php echo esc($item_value($item,'norm_reference')); ?></small><?php } ?></div><div class="col-lg-5"><div class="inspection-buttons btn-group w-100" role="group"><button type="button" class="btn btn-outline-success response-button <?php echo $value==='conforming'?'active':''; ?>" data-value="conforming"><?php echo app_lang('engenharia_conforming'); ?></button><button type="button" class="btn btn-outline-danger response-button <?php echo $value==='not_conforming'?'active':''; ?>" data-value="not_conforming"><?php echo app_lang('engenharia_nonconforming'); ?></button><button type="button" class="btn btn-outline-secondary response-button <?php echo $value==='not_applicable'?'active':''; ?>" data-value="not_applicable"><?php echo app_lang('engenharia_not_applicable'); ?></button></div><?php if(!empty($item_value($item,'not_verified_allowed'))){ ?><button type="button" class="btn btn-outline-secondary btn-lg w-100 mt10 response-button" data-value="not_verified"><?php echo app_lang('engenharia_not_verified'); ?></button><?php } ?><textarea class="form-control mt10 item-observation" placeholder="<?php echo app_lang('engenharia_observation'); ?>"><?php echo esc($resp->observation??''); ?></textarea><div class="nc-fields mt10 <?php echo $conforming===0?'':'hide'; ?>"><textarea class="form-control mb10 nc-description" placeholder="<?php echo app_lang('engenharia_nc_description'); ?>"></textarea><select class="form-select mb10 nc-criticality"><option value="medium">Média</option><option value="high">Alta</option><option value="critical">Crítica</option></select><textarea class="form-control mb10 nc-recommendation" placeholder="<?php echo app_lang('engenharia_nc_recommendation'); ?>"></textarea><input type="date" class="form-control nc-due-date" /></div><?php if($item_value($item,'requires_measurement')){ ?><div class="input-group mt10"><input class="form-control item-measurement" type="number" step="any" placeholder="<?php echo app_lang('engenharia_measurement'); ?>"><span class="input-group-text"><?php echo esc($item_value($item,'measurement_unit')); ?></span></div><?php } ?><?php if($item_value($item,'requires_photo')){ ?><form class="photo-form mt10" enctype="multipart/form-data"><input type="hidden" name="laudo_id" value="<?php echo $laudo->id; ?>"><input type="hidden" name="response_id" value="<?php echo (int)($resp->id??0); ?>"><input class="form-control" type="file" name="manualFiles[]" accept="image/*"><button class="btn btn-default btn-sm mt10 photo-submit" type="submit"><?php echo app_lang('engenharia_upload_photo'); ?></button></form><?php } ?><small class="text-muted response-meta"><?php echo $resp ? esc($resp->answered_at) . ' · ' . esc($resp->answered_by) : ''; ?></small></div></div></div><?php } ?></div></div><?php }}else{ ?><div class="alert alert-warning"><?php echo app_lang('engenharia_no_checklist'); ?></div><?php } ?><?php if($can_finish){ ?><div class="card"><div class="card-body"><button id="finish-inspection" class="btn btn-primary btn-lg"><i data-feather="check-circle" class="icon-16"></i> <?php echo app_lang('engenharia_finish_inspection'); ?></button></div></div><?php } ?></div></div></div>
<script>$(function(){var currentArea=0;function updateProgress(){var all=$('.inspection-item').length,answered=$('.inspection-item').filter(function(){return !$(this).data('pending');}).length;$('#inspection-progress-label').text(answered+' / '+all);$('#pending-count').text(all-answered);$('#inspection-progress-bar').css('width',(all?Math.round(answered/all*100):0)+'%');}$('.inspection-filter').on('click',function(){var f=$(this).data('filter');$('.inspection-filter').removeClass('active');$(this).addClass('active');$('.inspection-item').each(function(){var show=f==='all'||(f==='pending'&&$(this).data('pending'))||(f==='nonconforming'&&$(this).data('nonconforming'));$(this).toggle(show);});});$('.response-button').on('click',function(){var b=$(this),box=b.closest('.inspection-item'),value=b.data('value');$.post('<?php echo_uri('engenharia/laudos/inspection/save_response'); ?>',{laudo_id:<?php echo $laudo->id; ?>,item_id:box.data('item-id'),area_id:currentArea,response_value:value,observation:box.find('.item-observation').val(),numeric_value:box.find('.item-measurement').val(),nc_description:box.find('.nc-description').val(),nc_criticality:box.find('.nc-criticality').val(),nc_recommendation:box.find('.nc-recommendation').val(),nc_due_date:box.find('.nc-due-date').val()},function(r){if(r.success){box.find('.response-button').removeClass('active');b.addClass('active');box.data('pending',0).attr('data-pending',0).data('nonconforming',value==='not_conforming'?1:0).attr('data-nonconforming',value==='not_conforming'?1:0);box.toggleClass('is-pending',false).toggleClass('is-nonconforming',value==='not_conforming');box.find('.nc-fields').toggleClass('hide',value!=='not_conforming');updateProgress();appAlert.success(r.message,{duration:3000});}else appAlert.error(r.message);},'json');});$('.item-observation,.item-measurement,.nc-fields textarea,.nc-fields input,.nc-fields select').on('change',function(){var box=$(this).closest('.inspection-item');box.find('.response-button.active').first().trigger('click');});$('.photo-form').on('submit',function(e){e.preventDefault();var f=$(this);$.ajax({url:'<?php echo_uri('engenharia/laudos/inspection/save_photo'); ?>',type:'POST',data:new FormData(this),processData:false,contentType:false,dataType:'json',success:function(r){if(r.success)appAlert.success(r.message,{duration:3000});else appAlert.error(r.message);}});});$('#finish-inspection').on('click',function(){if($('#pending-count').text()!=='0'){appAlert.error('<?php echo app_lang('engenharia_required_pending'); ?>');return;}if(confirm('<?php echo app_lang('engenharia_confirm_finish'); ?>'))$.post('<?php echo_uri('engenharia/laudos/inspection/finish'); ?>',{laudo_id:<?php echo $laudo->id; ?>},function(r){if(r.success)location.reload();else appAlert.error(r.message);},'json');});});</script>
